def merge(head1, head2):
	mergeHead = dummy = Node(None)
	(curr1, curr2) = (head1, head2)
	while curr1 and curr2:
		if curr1.data <= curr2.data:
			dummy.bottom = curr1
			curr1 = curr1.bottom
		else:
			dummy.bottom = curr2
			curr2 = curr2.bottom
		dummy = dummy.bottom
	if curr1:
		dummy.bottom = curr1
	if curr2:
		dummy.bottom = curr2
	return mergeHead.bottom

def flatten(root):
	head = root
	currRoot = root.next
	while currRoot:
		head = merge(head, currRoot)
		currRoot = currRoot.next
	return root
